import {parseGameJson} from './game-json.js';

export const behaviorTaskMemoryKeys=new Set(['behaviorTaskMemoryGet','behaviorTaskMemorySet','behaviorTaskMemoryClear']);
export function validateBehaviorTaskMemoryQuery(key,args){if(!behaviorTaskMemoryKeys.has(key)||!args||typeof args.task!=='string'||!args.task||args.task.length>160||/[\x00-\x1f]/.test(args.task))throw Error('실행 태스크 메모리 핸들을 확인하세요.');if(key==='behaviorTaskMemorySet')return parseGameJson(args.json);}
function activation(runner,handle){if(!runner)return null;for(const m of runner.memory.values()){if(m.handle===handle&&(m.taskActive&&!m.resetting&&runner.running||m.aborting||m.finishing))return m;const child=m.child&&activation(m.child,handle);if(child)return child;}return null;}
export function behaviorTaskMemoryOperation(runner,key,args){const parsed=validateBehaviorTaskMemoryQuery(key,args);const m=activation(runner,args.task);if(!m)throw Error('해당 오브젝트의 실행·정리 중 태스크 메모리가 아니에요.');if(key==='behaviorTaskMemoryGet')return JSON.stringify(m.taskData||{});if(key==='behaviorTaskMemorySet')m.taskData=parsed;else delete m.taskData;return true;}
export function validateBehaviorTaskMemoryResult(key,value){if(key==='behaviorTaskMemoryGet'){parseGameJson(value);return value;}if(value!==true)throw Error('태스크 메모리 응답을 확인하세요.');return value;}
export const behaviorTaskMemoryContract=Object.freeze({keys:[...behaviorTaskMemoryKeys],ownership:'Per active task activation handle, scoped to the owning behavior-tree actor and nested subtree runner. Not blackboard/global/native static data. Allocate payload only on Set; do not serialize payload into debug task/instance snapshots.',lifetime:'Start/tick, onFinish notification and abort/deferred-abort cleanup can access the current activation. Completion, reset, force stop, abort retirement or actor/tree replacement releases it; stale/foreign handles reject, and restart has a new handle/empty memory.',payload:'Existing game JSON object depth32/nodes10000/array4096/text262144 limits; validate before replacement. Get returns detached serialized text; Clear releases payload. No per-tree task count cap.',control:'Same BP service operations and hb::AI::GetTaskMemory/SetTaskMemory/ClearTaskMemory. Live resource queries make same-call Set/Get visible immediately without per-frame full-memory debug snapshots; no whole-world C++ query packet.',limits:'Activation-owned JSON memory only; not a native BTTask inheritance/instancing model. Live writes are immediate, with existing native live-query budget and no transaction rollback after later caller failure.'});
